factorial.code:
Begin
    Integer Procedure Fact(N); Integer N;
        Fact := If N <= 1 Then 1 Else N * Fact(N - 1);

    OutInt(Fact(10), 0);
    OutImage
End;

higher-order.code:
Begin
    Integer Array Xs(1:10);
    Integer I;

    Boolean Procedure Even(X); Integer X; Even := Mod(X, 2) = 0;
    Integer Procedure Square(X); Integer X; Square := X * X;

    ! No lambdas: ALGOL-style procedure parameters do the job;
    Procedure FilterMap(A, N, Keep, F);
        Integer Array A; Integer N;
        Procedure Keep Is Boolean Procedure Keep(X); Integer X;;
        Procedure F Is Integer Procedure F(X); Integer X;;
    Begin
        Integer I; Text Sep;
        Sep :- "";
        For I := 1 Step 1 Until N Do
            If Keep(A(I)) Then
            Begin
                OutText(Sep); OutInt(F(A(I)), 0); Sep :- " "
            End;
        OutImage
    End;

    For I := 1 Step 1 Until 10 Do Xs(I) := I;
    FilterMap(Xs, 10, Even, Square)
End;

shapes.code:
Begin
    Class Shape(Title); Text Title;
        Virtual: Procedure Area Is Integer Procedure Area;;
    Begin
        Procedure Describe;
        Begin
            OutText(Title); OutText(": "); OutInt(Area, 0); OutImage
        End;
    End;

    Shape Class Rectangle(W, H); Integer W, H;
    Begin
        Integer Procedure Area; Area := W * H;
    End;

    Shape Class Triangle(B, H); Integer B, H;
    Begin
        Integer Procedure Area; Area := B * H // 2;
    End;

    Ref(Shape) S;
    S :- New Rectangle("Rectangle", 3, 4);
    S.Describe;
    S :- New Triangle("Triangle", 10, 3);
    S.Describe
End;

signature.code:
Begin
    ! Every Simula object can be a coroutine: Detach suspends it,
      Resume transfers control to another object where it left off;
    Class Player(Who); Text Who;
    Begin
        Ref(Player) Other;
        Integer I;
        Detach;
        For I := 1 Step 1 Until 3 Do
        Begin
            OutText(Who); OutInt(I, 2); OutImage;
            Resume(Other)
        End
    End;

    Ref(Player) Ping, Pong;
    Ping :- New Player("Ping");
    Pong :- New Player("Pong");
    Ping.Other :- Pong;
    Pong.Other :- Ping;
    Resume(Ping);
    OutText("Done"); OutImage
End;
